create extension if not exists pgcrypto;
create type client_status as enum ('active','archived'); create type campaign_status as enum ('active','completed','paused','cancelled'); create type occurrence_status as enum ('pending','completed','cancelled'); create type payment_status as enum ('pending','paid','cancelled'); create type payment_method as enum ('pix','credit_card','debit_card','bank_transfer','cash','other'); create type asset_type as enum ('image','link'); create type task_priority as enum ('low','medium','high'); create type task_status as enum ('pending','completed'); create type task_recurrence as enum ('none','daily','weekly','monthly');
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table public.clients(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,professional_name text,email text,phone text,instagram text,other_socials text,notes text,status client_status not null default 'active',archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.service_types(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,description text,default_price numeric(12,2) not null default 0 check(default_price>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,name));
create table public.campaigns(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,client_id uuid not null references public.clients(id) on delete restrict,title text not null,book_title text,author_name text,description text,start_date date,end_date date,status campaign_status not null default 'active',total_value numeric(12,2) not null default 0 check(total_value>=0),notes text,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date is null or start_date is null or end_date>=start_date));
create table public.campaign_services(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,campaign_id uuid not null references public.campaigns(id) on delete cascade,service_type_id uuid not null references public.service_types(id) on delete restrict,description text,quantity integer not null check(quantity>0),unit_price numeric(12,2) not null default 0 check(unit_price>=0),total_price numeric(12,2) not null default 0 check(total_price>=0),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.service_occurrences(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,campaign_service_id uuid not null references public.campaign_services(id) on delete cascade,sequence_number integer not null check(sequence_number>0),scheduled_date date,scheduled_time time,status occurrence_status not null default 'pending',completed_at timestamptz,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(campaign_service_id,sequence_number));
create table public.payments(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,client_id uuid not null references public.clients(id) on delete restrict,campaign_id uuid references public.campaigns(id) on delete set null,description text not null,amount numeric(12,2) not null check(amount>0),due_date date,paid_at timestamptz,payment_method payment_method,payment_method_custom text,status payment_status not null default 'pending',notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(payment_method <> 'other' or payment_method_custom is not null));
create table public.client_assets(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,client_id uuid not null references public.clients(id) on delete cascade,campaign_id uuid references public.campaigns(id) on delete set null,service_occurrence_id uuid references public.service_occurrences(id) on delete set null,title text not null,description text,asset_type asset_type not null,storage_path text,external_url text,original_filename text,mime_type text,size_bytes bigint,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((asset_type='image' and storage_path is not null) or (asset_type='link' and external_url is not null)));
create table public.tasks(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,title text not null,description text,due_date date,due_time time,priority task_priority not null default 'medium',status task_status not null default 'pending',recurrence task_recurrence not null default 'none',completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index on public.clients(owner_id,status); create index on public.campaigns(owner_id,client_id,status); create index on public.campaign_services(owner_id,campaign_id); create index on public.service_occurrences(owner_id,scheduled_date,status); create index on public.payments(owner_id,client_id,due_date,status); create index on public.tasks(owner_id,due_date,status); create index on public.client_assets(owner_id,client_id);
create or replace function public.assert_same_owner() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_table_name='campaigns' and not exists(select 1 from clients where id=new.client_id and owner_id=new.owner_id) then raise exception 'Cliente inválido'; end if; if tg_table_name='campaign_services' and (not exists(select 1 from campaigns where id=new.campaign_id and owner_id=new.owner_id) or not exists(select 1 from service_types where id=new.service_type_id and owner_id=new.owner_id)) then raise exception 'Relacionamento inválido'; end if; return new; end $$;
create trigger campaigns_owner before insert or update on public.campaigns for each row execute function public.assert_same_owner(); create trigger campaign_services_owner before insert or update on public.campaign_services for each row execute function public.assert_same_owner();
do $$ declare t text; begin foreach t in array array['clients','service_types','campaigns','campaign_services','service_occurrences','payments','client_assets','tasks'] loop execute format('create trigger %I_updated before update on public.%I for each row execute function public.set_updated_at()',t,t); execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for all to authenticated using (auth.uid()=owner_id) with check (auth.uid()=owner_id)',t||'_owner',t); end loop; end $$;
insert into storage.buckets(id,name,public) values ('client-assets','client-assets',false) on conflict(id) do update set public=false;
create policy "Assets privados por proprietário" on storage.objects for all to authenticated using(bucket_id='client-assets' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='client-assets' and (storage.foldername(name))[1]=auth.uid()::text);
